def _tr(status="pending"):
    return {"id": "tr_1", "source": "a", "destination": "b", "amount": 5, "currency": "EUR", "reference": "R-1", "status": status}


def _r(status, body=None, headers=None):
    return Response(status, headers or {}, json.dumps(body if body is not None else {}).encode())


def _err(status, code, headers=None):
    return _r(status, {"error": {"code": code, "message": ""}}, headers)


class Fake:
    def __init__(self, responses):
        self.responses = list(responses)
        self.sent = []
        self.slept = []

    def send(self, method, path, headers, body):
        self.sent.append((method, path, headers, body))
        r = self.responses.pop(0)
        if isinstance(r, Exception):
            raise r
        return r

    def sleep(self, seconds):
        self.slept.append(seconds)


class RetryTest(unittest.TestCase):
    def test_create_key_and_retries(self):
        t = Fake([ConnectionError(), _err(429, "rate_limited", {"retry-after": "7"}), _err(409, "idempotency_in_progress"), _r(201, _tr())])
        create_transfer(t, "R-1", "a", "b", 5, "EUR")
        key = "pl-transfer-" + hashlib.sha256(b"R-1").hexdigest()[:24]
        self.assertEqual([s[2] for s in t.sent], [{"Idempotency-Key": key}] * 4)
        self.assertEqual(len({json.dumps(s[3]) for s in t.sent}), 1)
        self.assertEqual(t.slept, [1, 7, 4])

    def test_last_failure_raises(self):
        t = Fake([_err(503, "unavailable")] * 4)
        with self.assertRaises(ApiError) as c:
            get_transfer(t, "tr_1")
        self.assertEqual((c.exception.status, c.exception.code), (503, "unavailable"))
        self.assertEqual(t.slept, [1, 2, 4])

    def test_capture_no_key(self):
        t = Fake([ConnectionError(), _r(200, {"id": "h", "account": "a", "amount": 5, "currency": "EUR", "reference": "x", "status": "captured", "captured_amount": 5})])
        capture_hold(t, "h", 5)
        self.assertEqual([s[2] for s in t.sent], [{}, {}])

    def test_reversal_checks_before_resend(self):
        t = Fake([ConnectionError(), _r(200, _tr("pending")), _err(429, "rate_limited"), _r(200, _tr("reversed"))])
        self.assertEqual(reverse_transfer(t, "tr_1").status, "reversed")
        self.assertEqual([s[0] for s in t.sent], ["POST", "GET", "POST", "POST"][:0] or ["POST", "GET", "POST", "POST"][:4])
        self.assertEqual(t.slept, [1, 2])

    def test_reversal_applied(self):
        t = Fake([_err(502, "bad_gateway"), _r(200, _tr("reversed"))])
        self.assertEqual(reverse_transfer(t, "tr_1").status, "reversed")
        self.assertEqual(len(t.sent), 2)
